package com.bidx.filter;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;
@WebFilter(urlPatterns={"/dashboard","/auction/create","/bid","/my-auctions","/my-bids","/watchlist"}) public class AuthenticationFilter implements Filter {public void doFilter(ServletRequest x,ServletResponse y,FilterChain c)throws IOException,ServletException{HttpServletRequest r=(HttpServletRequest)x;HttpServletResponse p=(HttpServletResponse)y;if(r.getSession(false)==null||r.getSession(false).getAttribute("user")==null){p.sendRedirect(r.getContextPath()+"/login");return;}c.doFilter(x,y);}}
